/ {
    // This block ensures that the alias 'bmi_ic2' points to the node
    // that we are defining below. The error "undefined node label 'bmi_ic2'"
    // suggests that an alias named 'bmi_ic2' is trying to reference a node
    // that is also labeled 'bmi_ic2', but that node is missing.
    aliases {
        bmi_ic2 = &bmi_ic2;
    };
};

// Assuming the BMI sensor is connected to I2C0. If your board uses a
// different I2C controller (e.g., i2c1), you should change '&i2c0'
// to '&i2c1' accordingly.
&i2c0 {
    // Ensure the I2C bus is enabled.
    status = "okay";

    // Define the BMI160 sensor node. The label 'bmi_ic2' is crucial here
    // as it's the one that the alias 'bmi_ic2' is trying to reference.
    // The 'compatible' string and 'reg' (I2C address) should match your
    // specific BMI sensor model and its address. Common addresses for
    // BMI160 are 0x68 or 0x69.
    bmi_ic2: bmi160@68 {
        compatible = "bosch,bmi160";
        reg = <0x68>;
        // An optional 'label' property for the device itself,
        // distinct from the node label 'bmi_ic2'.
        label = "BMI160_SENSOR_0";
    };
};
